insert into note_topics (id, module_code, slug, title, description, source_path, content_hash, page_count, created_at, updated_at) values ('nt_mapv112-bisection-method', 'MAPV112', 'mapv112-bisection-method', 'The bisection method', 'Halving an interval until it is small enough to call, and the one question the method keeps asking: is the answer above or below the midpoint?', 'topics/Bisection_Method.pdf', '86296ebe01e56db469c70fca9271ebcf2001083bc52b38fac8327e79e2c803c2', NULL, '2026-10-12T15:26:11.407Z', '2026-10-12T15:26:11.407Z')
