insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_mapv112-bisection-method#0', 'nt_mapv112-bisection-method', 'MAPV112', 0, 'What it does', 'The bisection method finds a root of a continuous function on an interval
where the sign changes. It repeatedly halves the interval and keeps the half
on which the function still changes sign.', 48, '2026-10-12T15:26:11.416Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_mapv112-bisection-method#1', 'nt_mapv112-bisection-method', 'MAPV112', 1, 'The theorem', 'Let $f$ be continuous on $[a, b]$ and suppose $f(a) \cdot f(b) < 0$. Then
there exists $c \in (a, b)$ with $f(c) = 0$.', 30, '2026-10-12T15:26:11.416Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_mapv112-bisection-method#2', 'nt_mapv112-bisection-method', 'MAPV112', 2, 'The algorithm', '1. Choose an interval $[a, b]$ with $f(a) \cdot f(b) < 0$.
2. Compute the midpoint $m = \frac{a + b}{2}$.
3. If $f(m) = 0$ then $m$ is the root and we stop.
4. Otherwise replace whichever endpoint has the same sign as $f(m)$, so the
   new interval is $\left[a, m\right]$ or $\left[m, b\right]$.
5. Repeat.

The interval strictly shrinks and stays bracketing the root, so the sequence
of midpoints converges.', 102, '2026-10-12T15:26:11.416Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_mapv112-bisection-method#3', 'nt_mapv112-bisection-method', 'MAPV112', 3, 'Error bound', 'After $n$ iterations the interval has width $\frac{b - a}{2^n}$, so the
midpoint is within $\frac{b - a}{2^{n+1}}$ of the root. Halving the interval
halves the error, which is the method''s weakness: convergence is only linear
compared with Newton''s method, which is quadratic.

To reach an error below $\varepsilon$, take

$$
n \geq \log_2 \left( \frac{b - a}{\varepsilon} \right).
$$', 96, '2026-10-12T15:26:11.416Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_mapv112-bisection-method#4', 'nt_mapv112-bisection-method', 'MAPV112', 4, 'Worked example', 'Take $f(x) = x^2 - 2$ on $[0, 2]$. Then $f(0) = -2$ and $f(2) = 2$, so the
sign changes and a root lies in the interval. The true root is
$\sqrt{2} \approx 1.41421356$.

- $m = 1$, $f(1) = -1$. Sign change lies in $[1, 2]$.
- $m = 1.5$, $f(1.5) = 0.25$. Sign change lies in $[1, 1.5]$.
- $m = 1.25$, $f(1.25) = -0.4375$. Sign change lies in $[1.25, 1.5]$.
- $m = 1.375$, $f(1.375) = -0.109375$. Sign change lies in $[1.375, 1.5]$.
- $m = 1.4375$, $f(1.4375) = 0.06640625$. Sign change lies in $[1.375, 1.4375]$.

After five iterations the midpoint is within
$\frac{2}{2^{6}} = 0.03125$ of the root.', 150, '2026-10-12T15:26:11.416Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_mapv112-bisection-method#5', 'nt_mapv112-bisection-method', 'MAPV112', 5, 'When to use it, and when not to', 'Use it when you have a continuous function, a guaranteed sign change, and no
formula for the derivative. Its reliability is the point: it cannot diverge,
it does not need $f''$, and every step is checkable by hand.

Do not use it when many roots lie in the interval, since the sign change may
bracket a different one, or when you need many digits, since the error falls
geometrically and Newton falls far faster once close.', 106, '2026-10-12T15:26:11.416Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_mapv112-bisection-method#6', 'nt_mapv112-bisection-method', 'MAPV112', 6, 'Stopping criterion', 'Stop when $\frac{b - a}{2} < \varepsilon$, or when $m$ rounds to the same
value as the previous midpoint, which is what a floating-point
implementation should check to avoid spinning once the interval is too
small to subdivide.', 57, '2026-10-12T15:26:11.416Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_matt101-limits#0', 'nt_matt101-limits', 'MATT101', 0, 'Limits and continuity', '> **This is a placeholder sample, not real notes.** It exists so the free
> tier has something to demonstrate the tutor reading from. Replace it with
> the real MATT101 notes before launch.', 48, '2026-10-12T15:26:10.335Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_matt101-limits#1', 'nt_matt101-limits', 'MATT101', 1, 'Definition of a limit', 'The limit of $f(x)$ as $x$ approaches $a$ is $L$ when, for every
$\varepsilon > 0$ there is a $\delta > 0$ such that

$$
0 < |x - a| < \delta \implies |f(x) - L| < \varepsilon.
$$

The function does not have to be defined at $a$, and does not have to take
the value $L$ there.', 69, '2026-10-12T15:26:10.335Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_matt101-limits#2', 'nt_matt101-limits', 'MATT101', 2, 'Continuity', '$f$ is continuous at $a$ when $\lim_{x \to a} f(x) = f(a)$. Equivalently, all
three of these hold: $f(a)$ is defined, $\lim_{x \to a} f(x)$ exists, and the
two are equal.', 43, '2026-10-12T15:26:10.335Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_matt101-limits#3', 'nt_matt101-limits', 'MATT101', 3, 'One-sided limits', '$\lim_{x \to a^-}$ and $\lim_{x \to a^+}$ exist separately. They need not be
equal — the corner of $f(x) = |x|$ at the origin has a left limit of $-1$
and a right limit of $1$, so the two-sided limit does not exist even though
both one-sided limits do.', 63, '2026-10-12T15:26:10.335Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;

insert into note_chunks (id, topic_id, module_code, chunk_index, heading, content, token_estimate, created_at) values ('nt_matt101-limits#4', 'nt_matt101-limits', 'MATT101', 4, 'Limits at infinity', '$\lim_{x \to \infty} f(x) = L$ means that for every $\varepsilon > 0$ there
is an $N$ such that $x > N$ implies $|f(x) - L| < \varepsilon$. It is a
statement about the tail of the function, not about a point.', 52, '2026-10-12T15:26:10.335Z')
  on conflict (id) do update set topic_id = excluded.topic_id, module_code = excluded.module_code, chunk_index = excluded.chunk_index, heading = excluded.heading, content = excluded.content, token_estimate = excluded.token_estimate, created_at = excluded.created_at;
